package com.cpf.starter.notification;import java.time.*;import java.util.*;public final class CpfNotificationWorker {private final JdbcCpfNotificationOutbox outbox;private final Map<String,CpfNotificationProvider> providers;private final CpfNotificationPreferencePolicy preferences;private final Clock clock;public CpfNotificationWorker(JdbcCpfNotificationOutbox o,List<CpfNotificationProvider> p,CpfNotificationPreferencePolicy policy,Clock c){outbox=o;preferences=policy;clock=c;Map<String,CpfNotificationProvider> m=new HashMap<>();for(var provider:p)if(m.putIfAbsent(provider.channel(),provider)!=null)throw new IllegalStateException("duplicate notification provider: "+provider.channel());providers=Map.copyOf(m);}public RunResult runOnce(String worker,int limit){int sent=0,retry=0;for(var r:outbox.claim(worker,limit)){var decision=preferences.evaluate(r,clock);if(!decision.allowed()){outbox.retry(r.notificationId(),decision.reason(),decision.resumeAt());retry++;continue;}var provider=providers.get(r.channel());if(provider==null){outbox.retry(r.notificationId(),"MISSING_PROVIDER",Instant.now(clock).plusSeconds(300));retry++;continue;}try{CpfNotificationResult result=provider.send(r);if(result==null)result=CpfNotificationResult.unknown(r.notificationId(),provider.channel(),"provider returned null");outbox.complete(result);sent++;}catch(RuntimeException ex){outbox.retry(r.notificationId(),safe(ex),Instant.now(clock).plusSeconds(30));retry++;}}return new RunResult(sent,retry);}private static String safe(Exception e){String m=e.getMessage();return m==null?e.getClass().getSimpleName():m.substring(0,Math.min(1000,m.length()));}public record RunResult(int completed,int retried){} }
